/**
 * Every question the monster can be asked, and the five grisly answers to each.
 * Pure data: no SDK calls, no DOM. Art for option `id` lives at
 * `public/art/parts/<id>.png` (generated by tools/art, see CLAUDE.md).
 */

export type SlotId =
  | 'head'
  | 'torso'
  | 'armR'
  | 'legL'
  | 'browEye'
  | 'armL'
  | 'legR'
  | 'heart'
  | 'tail'
  | 'horns'
  | 'maw'
  | 'wings'
  | 'head2'
  | 'chestEye'
  | 'spine'
  | 'arm3'
  | 'ears'
  | 'jaw'
  | 'brain'
  | 'spark';

export interface PartOption {
  id: string;
  name: string;
  /** One short line of flavour shown on the option card. */
  blurb: string;
}

export interface Question {
  slot: SlotId;
  /** Short label for the part, used in the chronicle ("Day 3 — Left Leg"). */
  part: string;
  /** The prompt shown to players. */
  prompt: string;
  options: readonly [PartOption, PartOption, PartOption, PartOption, PartOption];
}

