const BY_SLOT = new Map<SlotId, Question>(QUESTIONS.map((q) => [q.slot, q]));
const OPTION_INDEX = new Map<string, { question: Question; option: PartOption }>();
for (const question of QUESTIONS) {
  for (const option of question.options) OPTION_INDEX.set(option.id, { question, option });
}

export function questionForSlot(slot: SlotId): Question {
  const q = BY_SLOT.get(slot);
  if (!q) throw new Error(`Unknown slot ${slot}`);
  return q;
}

export function findOption(id: string): { question: Question; option: PartOption } | undefined {
  return OPTION_INDEX.get(id);
}
